    #1 $display("always nested <= %0d %0d %0d %0d", m[0][0], m[0][1], m[1][0], m[1][1]);
    w = '{'{10, 11, 12}, '{13, 14, 15}};
    w[1] = '{w[1][2], w[1][0], w[1][1]};
    #1 $display("always row = %0d %0d %0d %0d %0d %0d", w[0][0], w[0][1], w[0][2], w[1][0], w[1][1], w[1][2]);
    w = '{'{10, 11, 12}, '{13, 14, 15}};
    w[1] <= '{w[1][2], w[1][0], w[1][1]};
    #1 $display("always row <= %0d %0d %0d %0d %0d %0d", w[0][0], w[0][1], w[0][2], w[1][0], w[1][1], w[1][2]);
    w = '{'{10, 11, 12}, '{13, 14, 15}};
    w[1] = w[0];
    #1 $display("always row copy = %0d %0d %0d %0d %0d %0d", w[0][0], w[0][1], w[0][2], w[1][0], w[1][1], w[1][2]);
    w = '{'{10, 11, 12}, '{13, 14, 15}};
    w[1] <= w[0];
    #1 $display("always row copy <= %0d %0d %0d %0d %0d %0d", w[0][0], w[0][1], w[0][2], w[1][0], w[1][1], w[1][2]);
    p = '{10, 11, 12};
    p = '{p.y, p.z, p.x};
    #1 $display("always struct positional = %0d %0d %0d", p.x, p.y, p.z);
    p = '{10, 11, 12};
    p <= '{p.y, p.z, p.x};
    #1 $display("always struct positional <= %0d %0d %0d", p.x, p.y, p.z);
    p = '{10, 11, 12};
    p = '{z: p.x, x: p.z, y: p.x};
    #1 $display("always struct named = %0d %0d %0d", p.x, p.y, p.z);
    p = '{10, 11, 12};
    p <= '{z: p.x, x: p.z, y: p.x};
    #1 $display("always struct named <= %0d %0d %0d", p.x, p.y, p.z);
    p = '{10, 11, 12};
    p = '{y: p.z, default: p.y};
    #1 $display("always struct default = %0d %0d %0d", p.x, p.y, p.z);
    p = '{10, 11, 12};
    p <= '{y: p.z, default: p.y};
    #1 $display("always struct default <= %0d %0d %0d", p.x, p.y, p.z);
    q = '{'{10, 11, 12}, '{13, 14, 15}};
    q = '{q.b, q.a};
    #1 $display("always struct members = %0d %0d %0d %0d %0d %0d", q.a.x, q.a.y, q.a.z, q.b.x, q.b.y, q.b.z);
    q = '{'{10, 11, 12}, '{13, 14, 15}};
    q <= '{q.b, q.a};
    #1 $display("always struct members <= %0d %0d %0d %0d %0d %0d", q.a.x, q.a.y, q.a.z, q.b.x, q.b.y, q.b.z);
    h = '{'{10, 11}, 12};
    h = '{'{h.n, h.v[0]}, h.v[1]};
    #1 $display("always struct array member = %0d %0d %0d", h.v[0], h.v[1], h.n);
    h = '{'{10, 11}, 12};
    h <= '{'{h.n, h.v[0]}, h.v[1]};
    #1 $display("always struct array member <= %0d %0d %0d", h.v[0], h.v[1], h.n);
  end
endmodule
